/** Plain-language recommendations. Rules are fixed and visible, not generated by a model. */
import type { OptimizeResult, PriceResult, PromoResult } from "./types";
import type { ThresholdResult } from "./delivery";

export type Call = "go" | "test" | "hold" | "stop";
export interface Verdict { call: Call | null; headline: string; reason: string }

export const CALL_LABEL: Record<Call, string> = {
  go: "Do it", test: "Test before rolling out", hold: "Probably not", stop: "Don't do it",
};

/** Probability bands used everywhere: 80%+ go, 55-80% test, 25-55% hold, below 25% stop. */
export function callFor(probability: number): Call {
  if (probability >= 0.8) return "go";
  if (probability >= 0.55) return "test";
  return probability >= 0.25 ? "hold" : "stop";
}

const pct = (v: number) => `${Math.round(v * 100)}%`;
/** Signed, with a true minus sign: +$885, −$30. */
const money = (v: number) => `${v < 0 ? "\u2212" : v > 0 ? "+" : ""}$${Math.abs(Math.round(v)).toLocaleString("en-US")}`;
const umoney = (v: number) => `$${Math.abs(Math.round(v)).toLocaleString("en-US")}`;

export function priceVerdict(r: PriceResult, changed: boolean): Verdict {
  if (!changed) {
    return { call: null, headline: "Move a price to see what happens", reason: "Every price is at today's regular price." };
  }
  const call = callFor(r.probProfitUp);
  const d = r.delta.profit;
  const rev = r.delta.revenue.p50;
  const tradeOff = d.p50 > 0 && rev < 0 ? ` It gives up ${umoney(-rev)} of revenue to get there.` : "";
  return {
    call, headline: CALL_LABEL[call],
    reason: `Profit changes by ${money(d.p50)} (likely ${money(d.p10)} to ${money(d.p90)}) and improves in ${pct(r.probProfitUp)} of 400 runs.${tradeOff}`,
  };
}

export function promoVerdict(r: PromoResult, funding: number): Verdict {
  const call = callFor(r.probProfitable);
  const need = r.breakEvenFunding.p50;
  let reason = `Net profit ${money(r.profit.p50)} after the dip and lost sales on other products (likely ${money(r.profit.p10)} to ${money(r.profit.p90)}).`;
  if (call === "go" || call === "test") {
    reason += need > 0 ? ` It still works with supplier funding as low as ${pct(need)}.` : " It pays for itself with no supplier funding.";
  } else if (need <= 1) {
    reason += ` It breaks even once the supplier funds ${pct(need)} of the discount${funding > 0 ? `, up from ${pct(funding)} now` : ""}.`;
  } else {
    reason += " Even a fully funded discount does not break even.";
  }
  return { call, headline: CALL_LABEL[call], reason };
}

export function optimizerVerdict(r: OptimizeResult): Verdict {
  const moved = r.changePct.filter((c) => Math.abs(c) > 1e-6).length;
  if (!r.feasible) {
    return { call: "stop", headline: "These limits contradict each other", reason: "No set of prices meets all three limits at once." };
  }
  if (!moved) {
    return { call: "hold", headline: "Leave prices where they are", reason: "No change inside your limits improves expected profit." };
  }
  const atBound = r.atBound.filter((b) => b === "upper" || b === "lower").length;
  const call = callFor(r.probProfitUp);
  const gain = r.delta.profit;
  const share = r.expected.baselineProfit > 0 ? gain.p50 / r.expected.baselineProfit : 0;
  return {
    call, headline: CALL_LABEL[call],
    reason: `Changing ${moved} prices adds ${money(gain.p50)} a week (${pct(share)} of category profit, likely ${money(gain.p10)} to ${money(gain.p90)}). ${atBound} of ${moved} stop at a limit, so your limits, not the model, set those.`,
  };
}

export function deliveryVerdict(best: ThresholdResult): Verdict {
  const call = callFor(best.probBetter);
  const d = best.profitDelta;
  return {
    call, headline: call === "go" || call === "test" ? `Free delivery above $${best.threshold}` : "Keep charging the fee",
    reason: `Under your assumptions the best threshold changes profit by ${money(d.p50)} per 1,000 orders (likely ${money(d.p10)} to ${money(d.p90)}) and beats the flat fee in ${pct(best.probBetter)} of cases.`,
  };
}
